const { I2C, PLC, WATCHDOG, NET, BT } = require('./mock_hw');

// Capability Scope Configuration
const ALLOWED_I2C_ADDR = 0x76;
const FORBIDDEN_I2C_ADDR = 0x68;
const ALLOWED_MODBUS_START = 100;
const ALLOWED_MODBUS_END = 200;

// State Management
let currentI2CAddr = FORBIDDEN_I2C_ADDR; // Simulating initial error state

function validateI2C(addr) {
    return addr === ALLOWED_I2C_ADDR;
}

function validateModbus(reg) {
    return reg >= ALLOWED_MODBUS_START && reg <= ALLOWED_MODBUS_END;
}

function selfRepairI2C() {
    if (!validateI2C(currentI2CAddr)) {
        console.log(`[Self-Repair] Detected forbidden I2C address ${currentI2CAddr}. Correcting to ${ALLOWED_I2C_ADDR}.`);
        currentI2CAddr = ALLOWED_I2C_ADDR;
    }
}

async function main() {
    // Initialize System Health
    WATCHDOG.feed();

    // Step 1: Attempted Access with Potential Violation
    console.log('--- Phase 1: I2C Capability Scope Check ---');
    selfRepairI2C(); // Apply repair logic immediately

    // Verify state before proceeding
    if (!validateI2C(currentI2CAddr)) {
        throw new Error('CapabilityScope Violation Persisted');
    }

    // Execute Allowed Operation
    const data = I2C.read(currentI2CAddr, 0, 1);
    console.log(`I2C Read (0x${currentI2CAddr.toString(16)}): ${data}`);

    // Step 2: Modbus Capability Scope Check
    console.log('--- Phase 2: Modbus Capability Scope Check ---');

    // Attempting a read within bounds
    const modbusReg = 150; 

    if (!validateModbus(modbusReg)) {
        console.log(`[Self-Repair] Modbus register ${modbusReg} out of bounds. Adjusting.`);
        modbusReg = ALLOWED_MODBUS_START;
    }

    const val = PLC.modbusRead('host1', modbusReg);
    console.log(`Modbus Read (${modbusReg}): ${val}`);

    // Step 3: Network Verification
    console.log('--- Phase 3: Network Integrity ---');
    const pingResult = NET.ping('192.168.1.1');
    console.log(`Network Ping: ${pingResult}`);

    // Termination
    console.log('Execution terminated successfully.');
    process.exit(0);
}

main().catch(err => {
    console.error(err.message);
    WATCHDOG.emergencyStop();
    process.exit(1);
});

